add_filter( 'admin_footer_text', 'perfectpixel_admin_footer_text', 20 );

function perfectpixel_admin_footer_text() {
	$text = esc_html( '{{admin_footer_custom_text}}' );
	$url  = trim( '{{admin_footer_custom_url}}' );
	if ( $url ) {
		$text = '<a href="' . esc_url( $url ) . '" target="_blank" rel="noopener">' . $text . '</a>';
	}
	return '<span id="footer-thankyou">' . $text . '</span>';
}
